# Surah Al-Ma'ida (chapter 5) — part 2: ayat 11-20 (IDs 680-689)
SURAH = 5

ENTRIES = {
680: (
"اے ایمان والو! اللہ کی نعمت جو تم پر ہو یاد کرو — جب ایک قوم نے (تمہاری طرف) ہاتھ بڑھانے کا ارادہ کیا — پس اس نے تم سے ان کے ہاتھ روک دیے — اور اللہ سے ڈرو — اور ایمان والوں کو چاہیے کہ وہ اللہ پر بھروسہ کریں",
"""۱۔ اللہ نے تمہیں دشمنوں سے محفوظ رکھا — یہ اسی کی نعمت ہے۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللّٰہِ عَلَيْكُمْ إِذْ هَمَّ قَوْمٌ أَن يَبْسُطُوا إِلَيْكُمْ أَيْدِيَهُمْ فَكَفَّ أَيْدِيَهُمْ عَنكُمْ‘‘ — اے ایمان والو! اللہ کی نعمت جو تم پر ہو یاد کرو — جب ایک قوم نے (تمہاری طرف) ہاتھ بڑھانے کا ارادہ کیا — پس اس نے تم سے ان کے ہاتھ روک دیے — یعنی دشمن جب نقصان پہنچانے والا تھا تو اللہ نے اسے روک دیا۔
۳۔ ’’وَاتَّقُوا اللّٰہَ وَعَلَى اللّٰہِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ‘‘ — اور اللہ سے ڈرو — اور ایمان والوں کو چاہیے کہ وہ اللہ پر بھروسہ کریں — یعنی ظاہری دباؤ میں اللہ پر بھروسہ رکھو۔
۴۔ عملی سبق: اللہ کی نعمتیں یاد رکھو؛ ہر مشکل میں اسی پر بھروسہ کرو۔"""
),
681: (
"اور تحقیق اللہ نے بنی اسرائیل سے پختہ عہد لیا اور ہم نے ان میں سے بارہ نقیب (سردار) مقرر کیے — اور اللہ نے فرمایا: بے شک میں تمہارے ساتھ ہوں — اگر تم نماز قائم کرو گے اور زکوٰۃ دو گے اور میرے رسولوں پر ایمان لاؤ گے اور ان کی مدد کرو گے اور اللہ کو اچھی طرح قرض دو گے (خیرات کرو گے) تو میں تمہارے گناہ معاف کر دوں گا اور تمہاری ایسی جنتوں میں داخل کروں گا جن کے نیچے سے نہریں بہتی ہیں — پھر جو کوئی اس کے بعد تم میں سے کفر کرے — وہ سیدھے راستے سے بھٹک گیا",
"""۱۔ بنی اسرائیل سے بارہ نقیبوں کے ذریعے پختہ عہد — ایمان اور عمل دونوں کا۔
۲۔ ’’وَلَقَدْ أَخَذَ اللّٰہُ مِيثَاقَ بَنِي إِسْرَائِيلَ وَبَعَثْنَا مِنْهُمُ اثْنَيْ عَشَرَ نَقِيبًا‘‘ — اور تحقیق اللہ نے بنی اسرائیل سے پختہ عہد لیا اور ہم نے ان میں سے بارہ نقیب (سردار) مقرر کیے — یعنی بارہ قبیلوں کے سردار۔
۳۔ ’’وَقَالَ اللّٰہُ إِنِّي مَعَكُمْ لَئِنْ أَقَمْتُمُ الصَّلَاةَ وَآتَيْتُمُ الزَّكَاةَ‘‘ — اور اللہ نے فرمایا: بے شک میں تمہارے ساتھ ہوں — اگر تم نماز قائم کرو گے اور زکوٰۃ دو گے۔
۴۔ ’’وَآمَنتُم بِرُسُلِي وَعَزَّرْتُمُوهُمْ وَأَقْرَضْتُمُ اللّٰہَ قَرْضًا حَسَنًا‘‘ — اور میرے رسولوں پر ایمان لاؤ گے اور ان کی مدد کرو گے اور اللہ کو اچھی طرح قرض دو گے (خیرات کرو گے) — یعنی نیکی میں خرچ کرنا اللہ کو قرض دینا ہے۔
۵۔ ’’لَّأُكَفِّرَنَّ عَنكُمْ سَيِّئَاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ‘‘ — تو میں تمہارے گناہ معاف کر دوں گا اور تمہاری ایسی جنتوں میں داخل کروں گا جن کے نیچے سے نہریں بہتی ہیں — یعنی اللہ کے وعدے کے مطابق اجر۔
۶۔ ’’فَمَن كَفَرَ بَعْدَ ذَٰلِكَ مِنكُمْ فَقَدْ ضَلَّ سَوَاءَ السَّبِيلِ‘‘ — پھر جو کوئی اس کے بعد تم میں سے کفر کرے — وہ سیدھے راستے سے بھٹک گیا۔
۷۔ عملی سبق: نماز، زکوٰۃ اور نیکی پر پابند رہو؛ اللہ کا وعدہ سچا ہے۔"""
),
682: (
"پس ان کے عہد توڑنے کی وجہ سے ہم نے ان پر لعنت کی اور ان کے دل سخت کر دیے — وہ کلمات کو ان کے مقامات سے بدل دیتے ہیں — اور انہوں نے — جو انہیں یاد دلایا گیا تھا — اس کا ایک حصہ بھول گئے — اور آپ (نبی ﷺ) ان کی طرف سے ہمیشہ خیانت پر آگاہ ہوتے رہیں گے — سوائے چند ایک کے — پھر بھی آپ انہیں معاف اور درگزر کر دیں — بے شک اللہ نیکی کرنے والوں سے محبت کرتا ہے",
"""۱۔ بنی اسرائیل کا انجام — عہد شکنی کی سزا۔
۲۔ ’’فَبِمَا نَقْضِهِم مِّيثَاقَهُمْ لَعَنَّاهُمْ وَجَعَلْنَا قُلُوبَهُمْ قَاسِيَۃً‘‘ — پس ان کے عہد توڑنے کی وجہ سے ہم نے ان پر لعنت کی اور ان کے دل سخت کر دیے — یعنی عہد شکنی کا نقصان — دل سخت ہو جاتے ہیں۔
۳۔ ’’يُحَرِّفُونَ الْكَلِمَ عَن مَّوَاضِعِهِ‘‘ — وہ کلمات کو ان کے مقامات سے بدل دیتے ہیں — یعنی کتابِ اللہ میں تحریف — اہل تشیع کے نزدیک یہ قرآن ہی نہیں بلکہ اپنی کتابوں میں ردوبدل کرتے تھے — قرآن اللہ کے وعدے کے مطابق محفوظ ہے۔
۴۔ ’’وَنَسُوا حَظًّا مِّمَّا ذُكِّرُوا بِهِ‘‘ — اور انہوں نے — جو انہیں یاد دلایا گیا تھا — اس کا ایک حصہ بھول گئے۔
۵۔ ’’وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَائِنَۃٍ مِّنْهُمْ إِلَّا قَلِيلًا مِّنْهُمْ‘‘ — اور آپ (نبی ﷺ) ان کی طرف سے ہمیشہ خیانت پر آگاہ ہوتے رہیں گے — سوائے چند ایک کے۔
۶۔ ’’فَاعْفُ عَنْهُمْ وَاصْفَحْ إِنَّ اللّٰہَ يُحِبُّ الْمُحْسِنِينَ‘‘ — پھر بھی آپ انہیں معاف اور درگزر کر دیں — بے شک اللہ نیکی کرنے والوں سے محبت کرتا ہے — یعنی برائی کا جواب درگزر سے دو۔
۷۔ عملی سبق: عہد اور وعدہ پورا کرو؛ دوسروں کی خیانت پر معاف کرنا اللہ کی محبت کا سبب ہے۔"""
),
683: (
"اور وہ لوگ جنہوں نے کہا: ہم نصاریٰ ہیں — ان سے بھی ہم نے عہد لیا تھا — پھر انہوں نے — جو انہیں یاد دلایا گیا تھا — اس کا ایک حصہ بھول گئے — پس ہم نے قیامت تک ان کے درمیان دشمنی اور کینے کی آگ بھڑکا دی — اور عنقریب اللہ انہیں — جو وہ کرتے تھے — بتائے گا",
"""۱۔ نصاریٰ نے بھی عہد توڑا — نتیجہ: آپس کے اختلافات۔
۲۔ ’’وَمِنَ الَّذِينَ قَالُوا إِنَّا نَصَارَىٰ أَخَذْنَا مِيثَاقَهُمْ فَنَسُوا حَظًّا مِّمَّا ذُكِّرُوا بِهِ‘‘ — اور وہ لوگ جنہوں نے کہا: ہم نصاریٰ ہیں — ان سے بھی ہم نے عہد لیا تھا — پھر انہوں نے — جو انہیں یاد دلایا گیا تھا — اس کا ایک حصہ بھول گئے — یعنی نصاریٰ بھی پابندی نہیں کر سکے۔
۳۔ ’’فَأَغْرَيْنَا بَيْنَهُمُ الْعَدَاوَۃَ وَالْبَغْضَاءَ إِلَىٰ يَوْمِ الْقِيَامَۃِ‘‘ — پس ہم نے قیامت تک ان کے درمیان دشمنی اور کینے کی آگ بھڑکا دی — یعنی نصاریٰ کے فرقے آپس میں دشمن رہیں گے۔
۴۔ ’’وَسَوْفَ يُنَبِّئُهُمُ اللّٰہُ بِمَا كَانُوا يَصْنَعُونَ‘‘ — اور عنقریب اللہ انہیں — جو وہ کرتے تھے — بتائے گا — یعنی قیامت میں ان کا حساب ہوگا۔
۵۔ عملی سبق: اللہ کے عہد پر استقامت کرو؛ فرقوں میں تقسیم نہ ہو۔"""
),
684: (
"اے اہلِ کتاب! تمہارے پاس ہمارا رسول آ چکا ہے — جو تمہیں بیان کرتا ہے — کتاب میں سے — بہت ساری چیزیں جنہیں تم چھپاتے تھے — اور بہت سی (چیزیں) معاف بھی کرتا ہے — تمہارے پاس اللہ کی طرف سے ایک نور اور واضح کتاب آ چکی ہے",
"""۱۔ نبی ﷺ کا واضح پیغام — نور اور کتاب۔
۲۔ ’’يَا أَهْلَ الْكِتَابِ قَدْ جَاءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ كَثِيرًا مِّمَّا كُنتُمْ تُخْفُونَ مِنَ الْكِتَابِ وَيَعْفُو عَن كَثِيرٍ‘‘ — اے اہلِ کتاب! تمہارے پاس ہمارا رسول آ چکا ہے — جو تمہیں بیان کرتا ہے — کتاب میں سے — بہت ساری چیزیں جنہیں تم چھپاتے تھے — اور بہت سی (چیزیں) معاف بھی کرتا ہے — یعنی چھپائی ہوئی سچائیوں کو نبی ﷺ ظاہر کر دیتے ہیں۔
۳۔ ’’قَدْ جَاءَكُم مِّنَ اللّٰہِ نُورٌ وَكِتَابٌ مُبِينٌ‘‘ — تمہارے پاس اللہ کی طرف سے ایک نور اور واضح کتاب آ چکی ہے — یعنی نور سے مراد نبی ﷺ ہیں یا وہ روشنی جو قرآن لایا۔
۴۔ عملی سبق: نبی ﷺ کی لائی ہوئی سچائی کو قبول کرو؛ چھپاؤ نہ۔"""
),
685: (
"اللہ — جو کوئی اس کی رضا کی پیروی کرے — اسے امن کے راستوں کی طرف ہدایت دیتا ہے — اور انہیں اپنے حکم سے اندھیریوں سے نکال کر نور میں لاتا ہے — اور انہیں سیدھے راستے کی طرف ہدایت دیتا ہے",
"""۱۔ اللہ کی رضا کی پیروی — سیدھے راستے کی ہدایت۔
۲۔ ’’يَهْدِي بِهِ اللّٰہُ مَنِ اتَّبَعَ رِضْوَانَهُ سُبُلَ السَّلَامِ‘‘ — اللہ — جو کوئی اس کی رضا کی پیروی کرے — اسے امن کے راستوں کی طرف ہدایت دیتا ہے — یعنی اللہ کی رضا کی پیروی — سلامتی کے راستے۔
۳۔ ’’وَيُخْرِجُهُم مِّنَ الظُّلُمَاتِ إِلَى النُّورِ بِإِذْنِهِ‘‘ — اور انہیں اپنے حکم سے اندھیریوں سے نکال کر نور میں لاتا ہے — یعنی کفر سے ایمان کی روشنی میں۔
۴۔ ’’وَيَهْدِيهِمْ إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ‘‘ — اور انہیں سیدھے راستے کی طرف ہدایت دیتا ہے۔
۵۔ عملی سبق: اللہ کی رضا کے پیچھے چلو؛ اللہ تمہیں سیدھے راستے پر رکھے گا۔"""
),
686: (
"کافر ہو گئے وہ لوگ جنہوں نے کہا: اللہ ہی مسیح ابنِ مریم ہے — آپ کہہ دیں: اگر وہ مسیح ابنِ مریم — اس کی ماں اور زمین کے سب لوگوں کو ہلاک کرنے کا ارادہ کرے — تو اللہ کے مقابلے میں کون کچھ کر سکتا ہے — اس کا ہے جو آسمانوں، زمین اور ان کے درمیان ہے — وہ جو چاہتا ہے پیدا کرتا ہے — اور اللہ ہر چیز پر قدرت رکھتا ہے",
"""۱۔ عیسیٰؑ کو خدا کہنا — کفر ہے۔
۲۔ ’’لَقَدْ كَفَرَ الَّذِينَ قَالُوا إِنَّ اللّٰہَ هُوَ الْمَسِيحُ ابْنُ مَرْيَمَ‘‘ — کافر ہو گئے وہ لوگ جنہوں نے کہا: اللہ ہی مسیح ابنِ مریم ہے — یعنی یہ عقیدہ کفر ہے۔
۳۔ ’’قُلْ فَمَن يَمْلِكُ مِنَ اللّٰہِ شَيْئًا إِنْ أَرَادَ أَن يُهْلِكَ الْمَسِيحَ ابْنَ مَرْيَمَ وَأُمَّهُ وَمَن فِي الْأَرْضِ جَمِيعًا‘‘ — آپ کہہ دیں: اگر وہ مسیح ابنِ مریم — اس کی ماں اور زمین کے سب لوگوں کو ہلاک کرنے کا ارادہ کرے — تو اللہ کے مقابلے میں کون کچھ کر سکتا ہے — یعنی اللہ سب کچھ کر سکتا ہے — کوئی روک نہیں سکتا۔
۴۔ ’’وَلِلّٰہِ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا يَخْلُقُ مَا يَشَاءُ‘‘ — اس کا ہے جو آسمانوں، زمین اور ان کے درمیان ہے — وہ جو چاہتا ہے پیدا کرتا ہے — یعنی پیدائش کا اختیار صرف اللہ کا ہے۔
۵۔ ’’وَاللّٰہُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ‘‘ — اور اللہ ہر چیز پر قدرت رکھتا ہے۔
۶۔ عملی سبق: اللہ کو کامل قدرت اور اختیار والا مانو؛ غلو سے بچو۔"""
),
687: (
"اور یہود اور نصاریٰ نے کہا: ہم اللہ کی اولاد ہیں اور اس کے محبوب ہیں — آپ کہیں: پھر وہ تمہیں تمہارے گناہوں پر کیوں عذاب کرتا ہے — بلکہ تم لوگوں میں سے ایک مخلوق ہو جو اس نے پیدا کی ہے — وہ جسے چاہے بخش دے اور جسے چاہے عذاب دے — اللہ کا ہے جو آسمانوں، زمین اور ان کے درمیان ہے — اور اسی کی طرف (سب) لوٹ کر جانا ہے",
"""۱۔ اللہ کے محبوب ہونے کا جھوٹا دعویٰ — اللہ اپنے عمل کے بغیر کسی کو معاف نہیں کرتا۔
۲۔ ’’وَقَالَتِ الْيَهُودُ وَالنَّصَارَىٰ نَحْنُ أَبْنَاءُ اللّٰہِ وَأَحِبَّاؤُهُ‘‘ — اور یہود اور نصاریٰ نے کہا: ہم اللہ کی اولاد ہیں اور اس کے محبوب ہیں — یعنی ان کا غلط فخر۔
۳۔ ’’قُلْ فَلِمَ يُعَذِّبُكُم بِذُنُوبِكُم بَلْ أَنتُم بَشَرٌ مِّمَّنْ خَلَقَ‘‘ — آپ کہیں: پھر وہ تمہیں تمہارے گناہوں پر کیوں عذاب کرتا ہے — بلکہ تم لوگوں میں سے ایک مخلوق ہو جو اس نے پیدا کی ہے — یعنی گناہ کی سزا محبت کے دعوے کے برخلاف ہے۔
۴۔ ’’يَغْفِرُ لِمَن يَشَاءُ وَيُعَذِّبُ مَن يَشَاءُ‘‘ — وہ جسے چاہے بخش دے اور جسے چاہے عذاب دے — یعنی اللہ کا اختیار کامل ہے۔
۵۔ ’’وَلِلّٰہِ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا وَإِلَيْهِ الْمَصِيرُ‘‘ — اللہ کا ہے جو آسمانوں، زمین اور ان کے درمیان ہے — اور اسی کی طرف (سب) لوٹ کر جانا ہے۔
۶۔ عملی سبق: اللہ کا محبوب بننے کا دعویٰ چھوڑو؛ گناہوں کی سزا بھگتو (مت) — ایمان اور نیک عمل کرو۔"""
),
688: (
"اے اہلِ کتاب! تمہارے پاس ہمارا رسول آ چکا ہے — جو تمہیں بیان کرتا ہے — رسولوں کے درمیان ایک وقفہ (کے بعد) — کہ (تم یہ) نہ کہو: ہمارے پاس کوئی بشارت دینے والا اور کوئی ڈرانے والا آیا ہی نہیں — اب تمہارے پاس بشارت دینے والا اور ڈرانے والا آ گیا ہے — اور اللہ ہر چیز پر قدرت رکھتا ہے",
"""۱۔ نبی ﷺ کا آنا — رسولوں کے ایک وقفے کے بعد ہوا۔
۲۔ ’’يَا أَهْلَ الْكِتَابِ قَدْ جَاءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ عَلَىٰ فَتْرَۃٍ مِّنَ الرُّسُلِ‘‘ — اے اہلِ کتاب! تمہارے پاس ہمارا رسول آ چکا ہے — جو تمہیں بیان کرتا ہے — رسولوں کے درمیان ایک وقفہ (کے بعد) — یعنی حضرت عیسیٰؑ کے بعد نبی ﷺ کا ظہور ہوا۔
۳۔ ’’أَن تَقُولُوا مَا جَاءَنَا مِن بَشِيرٍ وَلَا نَذِيرٍ‘‘ — کہ (تم یہ) نہ کہو: ہمارے پاس کوئی بشارت دینے والا اور کوئی ڈرانے والا آیا ہی نہیں — یعنی اب یہ بہانہ ختم ہو گیا۔
۴۔ ’’فَقَدْ جَاءَكُم بَشِيرٌ وَنَذِيرٌ وَاللّٰہُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ‘‘ — اب تمہارے پاس بشارت دینے والا اور ڈرانے والا آ گیا ہے — اور اللہ ہر چیز پر قدرت رکھتا ہے۔
۵۔ عملی سبق: نبی ﷺ کو سچا سمجھو؛ اہل ایمان بنو۔"""
),
689: (
"اور جب موسیٰؑ نے اپنی قوم سے کہا: اے میری قوم! اللہ کی نعمت جو تم پر ہے یاد کرو — جب اس نے تم میں انبیاء بنائے اور تمہیں بادشاہ بنایا اور تمہیں وہ کچھ دیا جو جہانوں میں سے کسی کو نہیں دیا",
"""۱۔ بنی اسرائیل پر اللہ کے انعامات — انبیاء، بادشاہت اور فیاضی۔
۲۔ ’’وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِ يَا قَوْمِ اذْكُرُوا نِعْمَتَ اللّٰہِ عَلَيْكُمْ إِذْ جَعَلَ فِيكُمْ أَنْبِيَاءَ‘‘ — اور جب موسیٰؑ نے اپنی قوم سے کہا: اے میری قوم! اللہ کی نعمت جو تم پر ہے یاد کرو — جب اس نے تم میں انبیاء بنائے — یعنی بنی اسرائیل میں بے شمار انبیاء پیدا ہوئے۔
۳۔ ’’وَجَعَلَكُم مُّلُوكًا وَآتَاكُم مَّا لَمْ يُؤْتِ أَحَدًا مِّنَ الْعَالَمِينَ‘‘ — اور تمہیں بادشاہ بنایا اور تمہیں وہ کچھ دیا جو جہانوں میں سے کسی کو نہیں دیا — یعنی بنی اسرائیل کو اپنی قوم پر بھی بادشاہت ملی اور خصوصی انعامات۔
۴۔ عملی سبق: اللہ کے انعامات یاد رکھو؛ شکر ادا کرو۔"""
),
}
